res_poses = primitives.call(
    name='inspect_robowits_object_poses',
    context=None,
    names=['red block', 'target area', 'white block 1', 'white block 2', 'white block 3', 'white block 4'],
    query='get poses of all objects'
)
print("object poses ok:", res_poses.ok)
if res_poses.ok:
    for name, data in res_poses.output.get('objects', {}).items():
        print(name, "pos:", data.get('position'), "bounds:", data.get('bounds'))

print("res_poses.output keys:", list(res_poses.output.keys()))
for k, v in res_poses.output.items():
    print(k, type(v))
    if isinstance(v, dict):
        print(" ", list(v.keys()))

# Check poses to see if wb3 moved
res_poses2 = primitives.call(
    name='inspect_robowits_object_poses',
    context=None,
    names=['red block', 'white block 1', 'white block 2', 'white block 3'],
    query='check poses after push'
)
if res_poses2.ok:
    for name, data in res_poses2.output.get('object_poses', {}).items():
        print(name, "pos:", data.get('pos'), "euler:", data.get('euler'))
